func testAccSubnetIPv4PrefixForName(name string, salt int) string {
	h := fnv.New32a()
	_, _ = h.Write([]byte(name))
	base := h.Sum32() + uint32(salt)
	secondOctet := 16 + int(base%16)
	thirdOctet := int((base / 16) % 256)
	return fmt.Sprintf("10.%d.%d.0/24", secondOctet, thirdOctet)
}

func testAccSubnetIPv6PrefixForName(name string, salt int) string {
	h := fnv.New32a()
	_, _ = h.Write([]byte(name))
	base := h.Sum32() + uint32(salt)
	segment0 := 0x2001
	segment1 := 0x0db8
	segment2 := int((base >> 16) & 0xffff)
	segment3 := int(base & 0xffff)
	segment4 := int((base >> 8) & 0x00ff)
	segment5 := int(base & 0x00ff)
	segment6 := int((base >> 24) & 0x00ff)
	segment7 := 0
	return fmt.Sprintf("%x:%x:%x:%x:%x:%x:%x:%x/64", segment0, segment1, segment2, segment3, segment4, segment5, segment6, segment7)
}

